function deactivate(uint256 index) external {
    require(index < chapters.length, "missing chapter");
    chapters[index].active = false;
}

pragma solidity ^0.8.20;
contract ChapterRegistry {
    struct Chapter { uint256 id; string title; bool active; }
    Chapter[] public chapters;
    function addChapter(string calldata title) external { chapters.push(Chapter(chapters.length, title, true)); }
    function chapterTitle(uint256 index) external view returns (string memory) { require(index < chapters.length); return chapters[index].title; }
    function archive(uint256 index) external { require(index < chapters.length); chapters[index].active = false; }
}
